INSERT INTO public.biblioteca_vectores (id,coleccion,materia,contenido,num_articulo,fuente,metadata,embedding,jurisdiccion,fuente_tipo,es_norma_vigente,revision_pendiente,instrumento_id,num_articulo_norm,hash_contenido,ingest_batch,ingested_at) VALUES
('OLA12_LP_2007_01:LEY_PROPIEDAD:51','mayalex_normativos','02_CIVIL','La omisión o inexactitud de alguna o algunas de las circunstancias exigidas para las inscripciones, anotaciones preventivas y cancelaciones no perjudica la validez de ellas. Para que se declare la nulidad, es necesario que por causa de la expresada omisión o inexactitud resulte una inseguridad absoluta sobre las personas de los contratantes, su capacidad civil, el derecho adquirido o el inmueble que constituye su objeto.','51','Ley de Propiedad de Honduras (Decreto No. 82-2004)','{"norm_id":"HN:LEY_PROPIEDAD","instrumento_id":"LEY_PROPIEDAD","ingest_batch":"OLA12_LP_2007_01","ola":"OLA12","ordinal":51,"decreto":"82-2004","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición de la Corte Suprema de Justicia «Ley_de_la_Propiedad.pdf» (GNU Ghostscript, 12-abr-2007), sin notas al pie.","pdf_sha256":"ecdb725f72985a489643669300edee0f702a610bbb9c454f71daa84a6ce31785","article_sha256":"c90100513e9695d421e635c1075e585bc756f91ca8434836a811825dd4158ac9","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_PROPIEDAD','51','c90100513e9695d421e635c1075e585bc756f91ca8434836a811825dd4158ac9','OLA12_LP_2007_01',now()),
('OLA12_LP_2007_01:LEY_PROPIEDAD:52','mayalex_normativos','02_CIVIL','Las disposiciones legales relativas al Registro de la Propiedad Inmueble serán aplicables, respetando su naturaleza, a los demás registros en cuanto no contravengan las disposiciones especiales que la regulan.','52','Ley de Propiedad de Honduras (Decreto No. 82-2004)','{"norm_id":"HN:LEY_PROPIEDAD","instrumento_id":"LEY_PROPIEDAD","ingest_batch":"OLA12_LP_2007_01","ola":"OLA12","ordinal":52,"decreto":"82-2004","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición de la Corte Suprema de Justicia «Ley_de_la_Propiedad.pdf» (GNU Ghostscript, 12-abr-2007), sin notas al pie.","pdf_sha256":"ecdb725f72985a489643669300edee0f702a610bbb9c454f71daa84a6ce31785","article_sha256":"000bc6a4efa6ed9757df3db1711cce637eefcd42c055b90f71c13772222ee2d7","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_PROPIEDAD','52','000bc6a4efa6ed9757df3db1711cce637eefcd42c055b90f71c13772222ee2d7','OLA12_LP_2007_01',now()),
('OLA12_LP_2007_01:LEY_PROPIEDAD:53','mayalex_normativos','02_CIVIL','Los actos o contratos que deban inscribirse en los diferentes Registros, salvo los casos expresamente señalados por otras leyes, estarán sujetos al pago de las tasas siguientes:

1 Cuando el valor del acto o contrato fuese L20.00 indeterminado o no exceda de mil Lempiras;

2 Sobre el excedente de mil Lempiras se pagará L.1.50/millar o fracción de millar.

Los pagos se efectuarán empleando los medios electrónicos o físicos que autorice el Instituto de la Propiedad (IP).','53','Ley de Propiedad de Honduras (Decreto No. 82-2004)','{"norm_id":"HN:LEY_PROPIEDAD","instrumento_id":"LEY_PROPIEDAD","ingest_batch":"OLA12_LP_2007_01","ola":"OLA12","ordinal":53,"decreto":"82-2004","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición de la Corte Suprema de Justicia «Ley_de_la_Propiedad.pdf» (GNU Ghostscript, 12-abr-2007), sin notas al pie.","pdf_sha256":"ecdb725f72985a489643669300edee0f702a610bbb9c454f71daa84a6ce31785","article_sha256":"92dd947927130b4f3b59e35dce748c9016c9c566c85302875d2fa3500ee45129","ubicacion":[],"constancias":[{"nota":null,"tipo":"REFORMA_TACITA","decretos":["150-2010"],"texto":"Reformado por el Decreto No. 150-2010, posterior a la edición de 2007 que se usa como fuente. Las copias locales del decreto son escaneos sin capa de texto, por lo que la reforma no está integrada: el texto que se muestra es el anterior. CONTEXT vigente hasta integrar el texto de La Gaceta."}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":"CONTEXT","motivo":"CONTEXT vigente: reformado por D.150-2010 después de la edición de 2007; el texto de la reforma no está integrado (D5)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_PROPIEDAD','53','92dd947927130b4f3b59e35dce748c9016c9c566c85302875d2fa3500ee45129','OLA12_LP_2007_01',now()),
('OLA12_LP_2007_01:LEY_PROPIEDAD:54','mayalex_normativos','02_CIVIL','El Catastro Inmobiliario es un registro técnico administrativo, único y público está conformado por información geográfica sobre los bienes inmuebles con la identificación de los recursos naturales, agropecuarios y la infraestructura del país.

Contiene la información sobre las medidas y la geo-referenciación de los predios, su forma geométrica, superficie, linderos colindancias, límites territoriales municipales, departamentales y nacionales; ubicaciones, uso actual y potencial del suelo y demás atributos económicos y jurídicos que perfeccionen el inventario de los bienes inmuebles y recursos del país. Estará a cargo del Instituto de la Propiedad (IP).','54','Ley de Propiedad de Honduras (Decreto No. 82-2004)','{"norm_id":"HN:LEY_PROPIEDAD","instrumento_id":"LEY_PROPIEDAD","ingest_batch":"OLA12_LP_2007_01","ola":"OLA12","ordinal":54,"decreto":"82-2004","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición de la Corte Suprema de Justicia «Ley_de_la_Propiedad.pdf» (GNU Ghostscript, 12-abr-2007), sin notas al pie.","pdf_sha256":"ecdb725f72985a489643669300edee0f702a610bbb9c454f71daa84a6ce31785","article_sha256":"dfc85d16f60a151ff791ff6673c20cf2d745a286c077ffc830888ea3140805da","ubicacion":["TITULO IV","CATASTRO INMOBILARIO","CAPITULO I","OBJETO, PRINCIPIOS Y DEFINICIONES"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_PROPIEDAD','54','dfc85d16f60a151ff791ff6673c20cf2d745a286c077ffc830888ea3140805da','OLA12_LP_2007_01',now()),
('OLA12_LP_2007_01:LEY_PROPIEDAD:55','mayalex_normativos','02_CIVIL','Toda propiedad inmueble dentro del Territorio de República de Honduras debe estar catastrada.

Los titulares de dichos inmuebles tienen la obligación proporcionar la información nacional necesaria y el auxilio gratuito que les sea requerido para el cumplimiento de este fin.','55','Ley de Propiedad de Honduras (Decreto No. 82-2004)','{"norm_id":"HN:LEY_PROPIEDAD","instrumento_id":"LEY_PROPIEDAD","ingest_batch":"OLA12_LP_2007_01","ola":"OLA12","ordinal":55,"decreto":"82-2004","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición de la Corte Suprema de Justicia «Ley_de_la_Propiedad.pdf» (GNU Ghostscript, 12-abr-2007), sin notas al pie.","pdf_sha256":"ecdb725f72985a489643669300edee0f702a610bbb9c454f71daa84a6ce31785","article_sha256":"12ff6802c33db93f81bafa07ffb5b861b0dfe7b75e26d4bbc0e26c4984345494","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_PROPIEDAD','55','12ff6802c33db93f81bafa07ffb5b861b0dfe7b75e26d4bbc0e26c4984345494','OLA12_LP_2007_01',now()),
('OLA12_LP_2007_01:LEY_PROPIEDAD:56','mayalex_normativos','02_CIVIL','El registro de información catastral operará de conformidad con los procedimientos, manuales e instructivos aprobados por el Consejo Directivo del Instituto de la Propiedad (IP) que aseguren la óptima prestación de sus servicios y que sean autorizados para tal fin.

Este registro tendrá como función principal la de inscribir, mantener organizar, proveer y custodiar toda la información autorizada que resulte los levantamientos catastro regístrales por cada predio con su clave catastral individualizada.','56','Ley de Propiedad de Honduras (Decreto No. 82-2004)','{"norm_id":"HN:LEY_PROPIEDAD","instrumento_id":"LEY_PROPIEDAD","ingest_batch":"OLA12_LP_2007_01","ola":"OLA12","ordinal":56,"decreto":"82-2004","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición de la Corte Suprema de Justicia «Ley_de_la_Propiedad.pdf» (GNU Ghostscript, 12-abr-2007), sin notas al pie.","pdf_sha256":"ecdb725f72985a489643669300edee0f702a610bbb9c454f71daa84a6ce31785","article_sha256":"8459070cd70da55dc79f107dc709f60647abddbee994b24f8549ca327bc33526","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_PROPIEDAD','56','8459070cd70da55dc79f107dc709f60647abddbee994b24f8549ca327bc33526','OLA12_LP_2007_01',now()),
('OLA12_LP_2007_01:LEY_PROPIEDAD:57','mayalex_normativos','02_CIVIL','El catastro debe de estar vinculado con la información contenida en el Registro de la Propiedad. Debe de haber concordancia entre contenido de registro catastral y la realidad jurídica registral para producir los efectos de la seguridad jurídica que es objeto de la fé pública catastral.','57','Ley de Propiedad de Honduras (Decreto No. 82-2004)','{"norm_id":"HN:LEY_PROPIEDAD","instrumento_id":"LEY_PROPIEDAD","ingest_batch":"OLA12_LP_2007_01","ola":"OLA12","ordinal":57,"decreto":"82-2004","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición de la Corte Suprema de Justicia «Ley_de_la_Propiedad.pdf» (GNU Ghostscript, 12-abr-2007), sin notas al pie.","pdf_sha256":"ecdb725f72985a489643669300edee0f702a610bbb9c454f71daa84a6ce31785","article_sha256":"52f4ba31c01e2489040db0c45532f4a4f9e4634695e6a7b3f9f58c0bf70c79b1","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_PROPIEDAD','57','52f4ba31c01e2489040db0c45532f4a4f9e4634695e6a7b3f9f58c0bf70c79b1','OLA12_LP_2007_01',now()),
('OLA12_LP_2007_01:LEY_PROPIEDAD:58','mayalex_normativos','02_CIVIL','Se consideran centros asociados del Instituto de la Propiedad (IP) todas aquellas instituciones proyectos y programas públicos, nacionales o municipales, que desarrollen actividades catastrales, regístrales y de ordenamiento territorial.','58','Ley de Propiedad de Honduras (Decreto No. 82-2004)','{"norm_id":"HN:LEY_PROPIEDAD","instrumento_id":"LEY_PROPIEDAD","ingest_batch":"OLA12_LP_2007_01","ola":"OLA12","ordinal":58,"decreto":"82-2004","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición de la Corte Suprema de Justicia «Ley_de_la_Propiedad.pdf» (GNU Ghostscript, 12-abr-2007), sin notas al pie.","pdf_sha256":"ecdb725f72985a489643669300edee0f702a610bbb9c454f71daa84a6ce31785","article_sha256":"99e5dabc87bc2d68ea4d180bdf54f723a8f8cc85b18ec86d9ccc9638a0cf5065","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_PROPIEDAD','58','99e5dabc87bc2d68ea4d180bdf54f723a8f8cc85b18ec86d9ccc9638a0cf5065','OLA12_LP_2007_01',now()),
('OLA12_LP_2007_01:LEY_PROPIEDAD:59','mayalex_normativos','02_CIVIL','Toda la actividad catastral y de ordenamiento territorial ejecutada por centros asociados debe de adecuarse a lo establecido esta ley o las resoluciones que emita el Instituto de la Propiedad (IP) para garantizar la actualización y mantenimiento de un sistema de formación registro catastral.

Los Centros Asociados proporcionarán el Instituto de la Propiedad copias digitalizadas de los productos catastrales o de ordenamiento territorial que realicen.','59','Ley de Propiedad de Honduras (Decreto No. 82-2004)','{"norm_id":"HN:LEY_PROPIEDAD","instrumento_id":"LEY_PROPIEDAD","ingest_batch":"OLA12_LP_2007_01","ola":"OLA12","ordinal":59,"decreto":"82-2004","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición de la Corte Suprema de Justicia «Ley_de_la_Propiedad.pdf» (GNU Ghostscript, 12-abr-2007), sin notas al pie.","pdf_sha256":"ecdb725f72985a489643669300edee0f702a610bbb9c454f71daa84a6ce31785","article_sha256":"0da1ebc0187ee03698595480058d0c576b7d1ddc8f995607f38c9625dae9633f","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_PROPIEDAD','59','0da1ebc0187ee03698595480058d0c576b7d1ddc8f995607f38c9625dae9633f','OLA12_LP_2007_01',now()),
('OLA12_LP_2007_01:LEY_PROPIEDAD:60','mayalex_normativos','02_CIVIL','El Levantamiento Catastro Registral es el conjunto de actividades jurídicas, técnicas y administrativas orientadas a obtener oficio en forma sistemática, la información precisa rápida y descriptiva de todos los predios del territorio nacional.

El proceso del levantamiento Catastro Registral comprenderá las autoridades siguientes: Diagnostico Registral; Análisis de la información catastral; análisis e investigación Jurídica y Vista Pública Administrativa.','60','Ley de Propiedad de Honduras (Decreto No. 82-2004)','{"norm_id":"HN:LEY_PROPIEDAD","instrumento_id":"LEY_PROPIEDAD","ingest_batch":"OLA12_LP_2007_01","ola":"OLA12","ordinal":60,"decreto":"82-2004","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición de la Corte Suprema de Justicia «Ley_de_la_Propiedad.pdf» (GNU Ghostscript, 12-abr-2007), sin notas al pie.","pdf_sha256":"ecdb725f72985a489643669300edee0f702a610bbb9c454f71daa84a6ce31785","article_sha256":"9c3569d74c278b120b11de32ea37e0b903108fc7d8431b18c3dd21a06af997c0","ubicacion":["CAPITULO II","DEL PROCEDIMIENTO DE CATASTRO."],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_PROPIEDAD','60','9c3569d74c278b120b11de32ea37e0b903108fc7d8431b18c3dd21a06af997c0','OLA12_LP_2007_01',now()),
('OLA12_LP_2007_01:LEY_PROPIEDAD:61','mayalex_normativos','02_CIVIL','Los trabajos catastrales se efectuarán en zona del Territorio que se determine en la declaratoria respectiva. La declaratoria de una zona que será sometida al proceso catastral es responsabilidad del Consejo Directivo del Instituto de la Propiedad (IP) y será debidamente divulgada a través de los medios que aseguren la óptima cobertura e información sobre el proceso a nivel local y nacional.

La declaratoria será publicada con antelación en el Diario Oficial La Gaceta” en un diario de mayor circulación y mediante avisos fijados en los parajes públicos más frecuentes de los lugares en los que se realice proceso.

El Instituto de la Propiedad (IP) se asegurará que exista información suficiente sobre las zonas que serán objeto del Levantamiento Catastro Registral.','61','Ley de Propiedad de Honduras (Decreto No. 82-2004)','{"norm_id":"HN:LEY_PROPIEDAD","instrumento_id":"LEY_PROPIEDAD","ingest_batch":"OLA12_LP_2007_01","ola":"OLA12","ordinal":61,"decreto":"82-2004","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición de la Corte Suprema de Justicia «Ley_de_la_Propiedad.pdf» (GNU Ghostscript, 12-abr-2007), sin notas al pie.","pdf_sha256":"ecdb725f72985a489643669300edee0f702a610bbb9c454f71daa84a6ce31785","article_sha256":"06fca7f54a188f6959754586c8319195d8c99e2d4a9c85571b780827417b3453","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_PROPIEDAD','61','06fca7f54a188f6959754586c8319195d8c99e2d4a9c85571b780827417b3453','OLA12_LP_2007_01',now()),
('OLA12_LP_2007_01:LEY_PROPIEDAD:62','mayalex_normativos','02_CIVIL','Toda institución centralizada o descentralizada del gobierno que haya levantado su propio catastro lo pondrá a disposición del Instituto de la Propiedad (IP), dentro de un plazo de treinta (30) días contados a partir de la notificación correspondiente, para que se inicie el proceso de integración al registro de información catastral.

El incumplimiento de esta disposición acarreará responsabilidad administrativa, civil, y criminal conforme a la Ley.','62','Ley de Propiedad de Honduras (Decreto No. 82-2004)','{"norm_id":"HN:LEY_PROPIEDAD","instrumento_id":"LEY_PROPIEDAD","ingest_batch":"OLA12_LP_2007_01","ola":"OLA12","ordinal":62,"decreto":"82-2004","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición de la Corte Suprema de Justicia «Ley_de_la_Propiedad.pdf» (GNU Ghostscript, 12-abr-2007), sin notas al pie.","pdf_sha256":"ecdb725f72985a489643669300edee0f702a610bbb9c454f71daa84a6ce31785","article_sha256":"ae5266cf3b820cfa95031fc3f22e99a5aab0da69d436f5b8e91689d66381a4e2","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_PROPIEDAD','62','ae5266cf3b820cfa95031fc3f22e99a5aab0da69d436f5b8e91689d66381a4e2','OLA12_LP_2007_01',now()),
('OLA12_LP_2007_01:LEY_PROPIEDAD:63','mayalex_normativos','02_CIVIL','Los inmuebles deben ser delineados conforme a títulos, posesión o tenencia.','63','Ley de Propiedad de Honduras (Decreto No. 82-2004)','{"norm_id":"HN:LEY_PROPIEDAD","instrumento_id":"LEY_PROPIEDAD","ingest_batch":"OLA12_LP_2007_01","ola":"OLA12","ordinal":63,"decreto":"82-2004","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición de la Corte Suprema de Justicia «Ley_de_la_Propiedad.pdf» (GNU Ghostscript, 12-abr-2007), sin notas al pie.","pdf_sha256":"ecdb725f72985a489643669300edee0f702a610bbb9c454f71daa84a6ce31785","article_sha256":"56ba5c359fef6d994ea5acfd2c5e8243971c901380cbf6da53cf1edbd0383dd8","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_PROPIEDAD','63','56ba5c359fef6d994ea5acfd2c5e8243971c901380cbf6da53cf1edbd0383dd8','OLA12_LP_2007_01',now()),
('OLA12_LP_2007_01:LEY_PROPIEDAD:64','mayalex_normativos','02_CIVIL','El Instituto de la Propiedad (IP) antes de que se declare catastrada una zona o un área territorial exhibirá la información catastral levantada con sus correspondientes planos y mapas, incluyendo, la lista de los inmuebles y los nombres de los presuntos propietarios o poseedores a través de una Vista Pública Administrativa.

El inicio de la Vista Pública Administrativa será publicada con antelación en el Diario Oficial La Gaceta en un diario de mayor circulación en avisos fijados en los parajes públicos más frecuentados de los lugares en que se realice el proceso y por lo menos en un medio electrónico de comunicación masiva.

Les hará la advertencia que de no concurrir a las oficinas habilitadades al efecto, dentro de los treinta (30) días siguientes a la primera publicación, solicitando la corrección de errores u omisiones de la información publicada, la misma se tendrá por exacta y válida.','64','Ley de Propiedad de Honduras (Decreto No. 82-2004)','{"norm_id":"HN:LEY_PROPIEDAD","instrumento_id":"LEY_PROPIEDAD","ingest_batch":"OLA12_LP_2007_01","ola":"OLA12","ordinal":64,"decreto":"82-2004","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición de la Corte Suprema de Justicia «Ley_de_la_Propiedad.pdf» (GNU Ghostscript, 12-abr-2007), sin notas al pie.","pdf_sha256":"ecdb725f72985a489643669300edee0f702a610bbb9c454f71daa84a6ce31785","article_sha256":"673836f25ea7ee8dcab34a4dddc7e50ac2b1465bd06b3459735a87deddb9f7b5","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_PROPIEDAD','64','673836f25ea7ee8dcab34a4dddc7e50ac2b1465bd06b3459735a87deddb9f7b5','OLA12_LP_2007_01',now()),
('OLA12_LP_2007_01:LEY_PROPIEDAD:65','mayalex_normativos','02_CIVIL','Si después de realizada la Vista Pública Administrativa, se encontrare coincidencia entre la realidad física y la situación jurídica de los inmuebles y sus titulares el Instituto de la Propiedad (IP), emitirá resolución declarándolo predio catastrado regular. En caso contrario, se declarará como predio catastrado irregular.

Esta información pasará a formar parte del Sistema Nacional de Información de Registro Catastral para que surta los efectos jurídicos que correspondan en el Registro de la Propiedad y el Catastro.','65','Ley de Propiedad de Honduras (Decreto No. 82-2004)','{"norm_id":"HN:LEY_PROPIEDAD","instrumento_id":"LEY_PROPIEDAD","ingest_batch":"OLA12_LP_2007_01","ola":"OLA12","ordinal":65,"decreto":"82-2004","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición de la Corte Suprema de Justicia «Ley_de_la_Propiedad.pdf» (GNU Ghostscript, 12-abr-2007), sin notas al pie.","pdf_sha256":"ecdb725f72985a489643669300edee0f702a610bbb9c454f71daa84a6ce31785","article_sha256":"b72cd09754092babc9c79d96592c6478ea54b1590888cd3c4b183358af449b67","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_PROPIEDAD','65','b72cd09754092babc9c79d96592c6478ea54b1590888cd3c4b183358af449b67','OLA12_LP_2007_01',now()),
('OLA12_LP_2007_01:LEY_PROPIEDAD:66','mayalex_normativos','02_CIVIL','En los predios catastrados irregulares se levantará acta haciendo constar las circunstancias y se requerirá a los interesados para que concurran a una audiencia pública de conciliación ante el Instituto de la Propiedad (IP) dentro del término de quince (15) días.

Si las partes se conciliaren se levantará acta haciendo constar tal circunstancia y se declarará regular el predio catastrado.

Si las partes no concilian quedará agotado el procedimiento administrado quedando expedita la vía judicial de conformidad con el Titulo VI de la presente Ley, si no acordaren arbitraje.','66','Ley de Propiedad de Honduras (Decreto No. 82-2004)','{"norm_id":"HN:LEY_PROPIEDAD","instrumento_id":"LEY_PROPIEDAD","ingest_batch":"OLA12_LP_2007_01","ola":"OLA12","ordinal":66,"decreto":"82-2004","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición de la Corte Suprema de Justicia «Ley_de_la_Propiedad.pdf» (GNU Ghostscript, 12-abr-2007), sin notas al pie.","pdf_sha256":"ecdb725f72985a489643669300edee0f702a610bbb9c454f71daa84a6ce31785","article_sha256":"372c6d5907b6abbfa13be641436bb2840902b2e11cc8f375f859119171895c32","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_PROPIEDAD','66','372c6d5907b6abbfa13be641436bb2840902b2e11cc8f375f859119171895c32','OLA12_LP_2007_01',now()),
('OLA12_LP_2007_01:LEY_PROPIEDAD:67','mayalex_normativos','02_CIVIL','Una vez realizada la Vista Pública Administrativa y agotado el proceso de validación del Levantamiento Catastro Registral de una zona catastral, el Instituto de la Propiedad (IP) procederá a declarar la zona como “Zona Catastrada”.

Para los predios catastrados regulares se abrirá el folio real correspondiente.','67','Ley de Propiedad de Honduras (Decreto No. 82-2004)','{"norm_id":"HN:LEY_PROPIEDAD","instrumento_id":"LEY_PROPIEDAD","ingest_batch":"OLA12_LP_2007_01","ola":"OLA12","ordinal":67,"decreto":"82-2004","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición de la Corte Suprema de Justicia «Ley_de_la_Propiedad.pdf» (GNU Ghostscript, 12-abr-2007), sin notas al pie.","pdf_sha256":"ecdb725f72985a489643669300edee0f702a610bbb9c454f71daa84a6ce31785","article_sha256":"92eb50c557208d0ce96be970e67a746fcd09fcc19ffe4528cbaa9d7becb93833","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_PROPIEDAD','67','92eb50c557208d0ce96be970e67a746fcd09fcc19ffe4528cbaa9d7becb93833','OLA12_LP_2007_01',now()),
('OLA12_LP_2007_01:LEY_PROPIEDAD:68','mayalex_normativos','02_CIVIL','El mapa catastral vinculado a planos de lotificación, urbanización o zonificación de ordenamiento territorial en el que se definan los bienes inmuebles de uso público como parques, calles, avenidas, puentes, riberas, playas, litorales, áreas protegidas, obras de servicio social o público. Los bienes fiscales, así como los bienes destinados a estos propósitos o para áreas verdes constituyen título de propiedad a favor del Estado o del Municipio, según corresponda.','68','Ley de Propiedad de Honduras (Decreto No. 82-2004)','{"norm_id":"HN:LEY_PROPIEDAD","instrumento_id":"LEY_PROPIEDAD","ingest_batch":"OLA12_LP_2007_01","ola":"OLA12","ordinal":68,"decreto":"82-2004","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición de la Corte Suprema de Justicia «Ley_de_la_Propiedad.pdf» (GNU Ghostscript, 12-abr-2007), sin notas al pie.","pdf_sha256":"ecdb725f72985a489643669300edee0f702a610bbb9c454f71daa84a6ce31785","article_sha256":"a650d08fe348198e56f8104282d70ce6d03078b360c4b403edcbbe442cb878c6","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_PROPIEDAD','68','a650d08fe348198e56f8104282d70ce6d03078b360c4b403edcbbe442cb878c6','OLA12_LP_2007_01',now()),
('OLA12_LP_2007_01:LEY_PROPIEDAD:69','mayalex_normativos','02_CIVIL','Se declara de prioridad nacional la regularización y solución de conflictos sobre la tenencia, posesión y propiedad de bienes inmuebles, la incorporación de los mismos al Catastro nacional, la titulación e inscripción en el Registro de la Propiedad Inmueble.','69','Ley de Propiedad de Honduras (Decreto No. 82-2004)','{"norm_id":"HN:LEY_PROPIEDAD","instrumento_id":"LEY_PROPIEDAD","ingest_batch":"OLA12_LP_2007_01","ola":"OLA12","ordinal":69,"decreto":"82-2004","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición de la Corte Suprema de Justicia «Ley_de_la_Propiedad.pdf» (GNU Ghostscript, 12-abr-2007), sin notas al pie.","pdf_sha256":"ecdb725f72985a489643669300edee0f702a610bbb9c454f71daa84a6ce31785","article_sha256":"2408d8aa1b65d4d0b9420fd64e34f3ab2f2e828647861a84b8cc24fc9d4ff010","ubicacion":["TITULO V","DE LA REGULARIZACIÓN","CAPITULO I","ASPECTOS GENERALES"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_PROPIEDAD','69','2408d8aa1b65d4d0b9420fd64e34f3ab2f2e828647861a84b8cc24fc9d4ff010','OLA12_LP_2007_01',now()),
('OLA12_LP_2007_01:LEY_PROPIEDAD:70','mayalex_normativos','02_CIVIL','Los procedimientos de regularización que permitan la solución pacifica, expedita, económica y segura de estos conflictos se regirán por las dispocisiones contenidas en este Título.

Salvo que la ley expresamente lo permita, estos procedimientos no podrán ser aplicados en zonas sujetas a regimenes especiales.','70','Ley de Propiedad de Honduras (Decreto No. 82-2004)','{"norm_id":"HN:LEY_PROPIEDAD","instrumento_id":"LEY_PROPIEDAD","ingest_batch":"OLA12_LP_2007_01","ola":"OLA12","ordinal":70,"decreto":"82-2004","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición de la Corte Suprema de Justicia «Ley_de_la_Propiedad.pdf» (GNU Ghostscript, 12-abr-2007), sin notas al pie.","pdf_sha256":"ecdb725f72985a489643669300edee0f702a610bbb9c454f71daa84a6ce31785","article_sha256":"7c1b38fef254950d698dd9533c6467914aacb418a4eace8d17495d91bb0678bc","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_PROPIEDAD','70','7c1b38fef254950d698dd9533c6467914aacb418a4eace8d17495d91bb0678bc','OLA12_LP_2007_01',now()),
('OLA12_LP_2007_01:LEY_PROPIEDAD:71','mayalex_normativos','02_CIVIL','se consideran zonas sujetas a regimenes especiales las siguientes:

1 Bosques nacionales;:

2 Las áreas protegidas; y,

3 Los parques nacionales.

Las leyes especiales que correspondan determinarán la forma en la que podrá hacerse la regulación de los bienes inmuebles ubicados dentro de esas zonas.','71','Ley de Propiedad de Honduras (Decreto No. 82-2004)','{"norm_id":"HN:LEY_PROPIEDAD","instrumento_id":"LEY_PROPIEDAD","ingest_batch":"OLA12_LP_2007_01","ola":"OLA12","ordinal":71,"decreto":"82-2004","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición de la Corte Suprema de Justicia «Ley_de_la_Propiedad.pdf» (GNU Ghostscript, 12-abr-2007), sin notas al pie.","pdf_sha256":"ecdb725f72985a489643669300edee0f702a610bbb9c454f71daa84a6ce31785","article_sha256":"1c89ef320ff0786023bb6717fd3e1ac705b2881db95fd4f312094562c984af3d","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_PROPIEDAD','71','1c89ef320ff0786023bb6717fd3e1ac705b2881db95fd4f312094562c984af3d','OLA12_LP_2007_01',now()),
('OLA12_LP_2007_01:LEY_PROPIEDAD:72','mayalex_normativos','02_CIVIL','El proceso de regularización comprenderá las etapas siguientes:

1 Declaración de un predio catastrado irregular;

2 Declaratoria de Regularización: la cual determinará la naturaleza jurídica, delimitación y extensión del área sujeta a regularización;

3 Levantamiento del Censo: Encuesta socioeconómica de los habitantes;

4 Nombramiento de facilitadores del proceso de regularización por parte de la comunidad;

5 Definición de la forma de titulación: individual, colectiva o mixta por parte de la comunidad beneficiada,

6 Aplicación de los mecanismos de regularización definidos en este título;

7 Pago de indemnización en caso de expropiación; y,

8 Titulación y registro.','72','Ley de Propiedad de Honduras (Decreto No. 82-2004)','{"norm_id":"HN:LEY_PROPIEDAD","instrumento_id":"LEY_PROPIEDAD","ingest_batch":"OLA12_LP_2007_01","ola":"OLA12","ordinal":72,"decreto":"82-2004","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición de la Corte Suprema de Justicia «Ley_de_la_Propiedad.pdf» (GNU Ghostscript, 12-abr-2007), sin notas al pie.","pdf_sha256":"ecdb725f72985a489643669300edee0f702a610bbb9c454f71daa84a6ce31785","article_sha256":"1cf52b17b9f9873cdf215a145000b002e5680df239b132a40c039a488cc2e0eb","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_PROPIEDAD','72','1cf52b17b9f9873cdf215a145000b002e5680df239b132a40c039a488cc2e0eb','OLA12_LP_2007_01',now()),
('OLA12_LP_2007_01:LEY_PROPIEDAD:73','mayalex_normativos','02_CIVIL','El proceso de regularización será iniciado de oficio o a petición de parte por el Instituto de la Propiedad (IP) a través de un Programa Nacional de Regularización Predial en tierras urbanas y rurales comprendidas dentro de alguno de los casos siguientes;

1 En las de naturaleza privada cuyos poseedores carezcan de documento inscribible;

2 Aquellas cuya naturaleza jurídica no este definida en las que se encuentren asentamientos humanos;

3 En las de naturaleza privada en disputa por particulares en las que se encuentran asentamientos humanos;

4 En las de naturaleza privada cuyos poseedores cumplan con los requisitos para adquirir por prescripción;

5 Las ejidales;

6 Las nacionales rurales detentadas por personas naturales hasta por veinticinco (25) hectáreas;

7 Las que careciendo de título sean poseídas por grupos étnicos;

8 Los terrenos de naturaleza fiscal donde hayan asentamientos humanos.','73','Ley de Propiedad de Honduras (Decreto No. 82-2004)','{"norm_id":"HN:LEY_PROPIEDAD","instrumento_id":"LEY_PROPIEDAD","ingest_batch":"OLA12_LP_2007_01","ola":"OLA12","ordinal":73,"decreto":"82-2004","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición de la Corte Suprema de Justicia «Ley_de_la_Propiedad.pdf» (GNU Ghostscript, 12-abr-2007), sin notas al pie.","pdf_sha256":"ecdb725f72985a489643669300edee0f702a610bbb9c454f71daa84a6ce31785","article_sha256":"2beb0be757a379862397ca20af5fcbb1711e6cbf7c5dd6a5043910f142f7e5f7","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_PROPIEDAD','73','2beb0be757a379862397ca20af5fcbb1711e6cbf7c5dd6a5043910f142f7e5f7','OLA12_LP_2007_01',now()),
('OLA12_LP_2007_01:LEY_PROPIEDAD:74','mayalex_normativos','02_CIVIL','Los derechos inscritos en dominio útil sobre bienes inmuebles nacionales o ejidales otorgados antes del 1 de enero de 1991 a la persona que a entrada en vigencia de esta Ley se encuentren usando, habitando o teniendo personalmente o por tercero a nombre suyo adquieren la condición de dominio pleno en base al título de dominio útil originalmente otorgado siempre que no se encuentren en disputa y no estén comprendidos en espacio de uso público o sujetos a afectaciones por razones de utilidad pública.

Se confirman los actos y contratos celebrados sobre los mismos con anterioridad a la vigencia de la presente Ley.

Estos derechos no podrán exceder más de veinticinco (25) hectáreas en el área rural cuando se trata de persona natural y de una (1) hectárea en el área urbana. Sobre los excedentes en que se encuentren mejoras que se reputan inmuebles, los que se encuentren usando, habitando o teniendo personalmente o por terceros a nombre suyo podrán solicitar, antes las autoridades que corresponda, el dominio pleno cuando cumplan con los requisitos establecidos en las leyes especiales aplicables.

Una comisión integrada por delegados del Instituto de la Propiedad, el Instituto Nacional Agrario (INA) y la municipalidad que corresponda, verificarán los predios que se acogen a este beneficio.

Los títulos que se ajusten a lo preceptuado en el párrafo primero del presente Artículo serán susceptibles de acción de nulidad ante el órgano jurisdiccional competente conforme al procedimiento especial establecido en la presente Ley. La misma podrá ser deducida por cualquier interesado o por el Instituto de la Propiedad (IP):','74','Ley de Propiedad de Honduras (Decreto No. 82-2004)','{"norm_id":"HN:LEY_PROPIEDAD","instrumento_id":"LEY_PROPIEDAD","ingest_batch":"OLA12_LP_2007_01","ola":"OLA12","ordinal":74,"decreto":"82-2004","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición de la Corte Suprema de Justicia «Ley_de_la_Propiedad.pdf» (GNU Ghostscript, 12-abr-2007), sin notas al pie.","pdf_sha256":"ecdb725f72985a489643669300edee0f702a610bbb9c454f71daa84a6ce31785","article_sha256":"2c9a16d0d6af773d136eddfba351d7043113010637f771c06aa1f1cb843a9e08","ubicacion":["CAPITULO II","MECANISMO DE REGULARIZACIÓN","SECCION PRIMERA","CONSOLIDACIÓN DE DERECHOS SOBRE BIENES EJIDALES","O NACIONALES."],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_PROPIEDAD','74','2c9a16d0d6af773d136eddfba351d7043113010637f771c06aa1f1cb843a9e08','OLA12_LP_2007_01',now()),
('OLA12_LP_2007_01:LEY_PROPIEDAD:75','mayalex_normativos','02_CIVIL','Las personas naturales que por un periodo continuo menor de diez (10) años se encuentren ocupando predios rurales no mayores de cinco (5) hectáreas ubicados en tierras nacionales o fiscales, serán tituladas por el Instituto de la Propiedad (IP) siempre y cuando no estén comprendidas en espacios de dominio público o de otras afectaciones de beneficios común o por causa de utilidad pública.

Esta última disposición es aplicable a la titulación contemplada en el artículo anterior.','75','Ley de Propiedad de Honduras (Decreto No. 82-2004)','{"norm_id":"HN:LEY_PROPIEDAD","instrumento_id":"LEY_PROPIEDAD","ingest_batch":"OLA12_LP_2007_01","ola":"OLA12","ordinal":75,"decreto":"82-2004","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición de la Corte Suprema de Justicia «Ley_de_la_Propiedad.pdf» (GNU Ghostscript, 12-abr-2007), sin notas al pie.","pdf_sha256":"ecdb725f72985a489643669300edee0f702a610bbb9c454f71daa84a6ce31785","article_sha256":"13281019168e2177b1ae4efb58f4a1be5c0c4d5b90a6296829e155ecdee268c9","ubicacion":[],"constancias":[{"nota":null,"tipo":"REFORMA_TACITA","decretos":["205-2012"],"texto":"Reformado por el Decreto No. 205-2012, posterior a la edición de 2007 que se usa como fuente. Las copias locales del decreto son escaneos sin capa de texto, por lo que la reforma no está integrada: el texto que se muestra es el anterior. CONTEXT vigente hasta integrar el texto de La Gaceta."}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":"CONTEXT","motivo":"CONTEXT vigente: reformado por D.205-2012 después de la edición de 2007; el texto de la reforma no está integrado (D5)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_PROPIEDAD','75','13281019168e2177b1ae4efb58f4a1be5c0c4d5b90a6296829e155ecdee268c9','OLA12_LP_2007_01',now()),
('OLA12_LP_2007_01:LEY_PROPIEDAD:76','mayalex_normativos','02_CIVIL','Para los efectos del procedimiento establecido en este capítulo se presumirá que toda concesión de dominio hecha por las municipalidades sobre sus ejidos antes de la entrada en vigencia de las municipalidades contenida en el Decreto No. 134-90 de fecha 29 de octubre de 1990 fue hecha en dominio útil, salvo que señale expresamente en el título original de conseción inscrito en los registros públicos que la propiedad se dio en venta o se concedió en dominio propio. En todo caso, se presume la buena fe.

Para los efectos de la presente Ley se entiende por dominio útil el hecho de uso o habitación.','76','Ley de Propiedad de Honduras (Decreto No. 82-2004)','{"norm_id":"HN:LEY_PROPIEDAD","instrumento_id":"LEY_PROPIEDAD","ingest_batch":"OLA12_LP_2007_01","ola":"OLA12","ordinal":76,"decreto":"82-2004","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición de la Corte Suprema de Justicia «Ley_de_la_Propiedad.pdf» (GNU Ghostscript, 12-abr-2007), sin notas al pie.","pdf_sha256":"ecdb725f72985a489643669300edee0f702a610bbb9c454f71daa84a6ce31785","article_sha256":"4feaba94a86c79cfda8ebccea7af5ad68d41d5d0c8207a4dbec1da7ee4cd75f0","ubicacion":["SECCION SEGUNDA","PRESUNCIÓN DE DOMINIO ÚTIL DE USO O HABITACIÓN","SOBRE TIERRAS DE EJIDOS."],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_PROPIEDAD','76','4feaba94a86c79cfda8ebccea7af5ad68d41d5d0c8207a4dbec1da7ee4cd75f0','OLA12_LP_2007_01',now()),
('OLA12_LP_2007_01:LEY_PROPIEDAD:77','mayalex_normativos','02_CIVIL','Se declara de necesidad pública la regularización la propiedad en inmuebles en los que se encuentren asentamientos humanos establecidos desde antes del 1 de junio de 1999 y concurra cualquiera de las circunstancias siguientes:

1 Que no sea posible establecerse quien es su legitimo propietario en vista de alegarse varios títulos de propiedad; y/o,

2 Que la titularidad o validez de esos derechos de propiedad sea disputada, judicial o extrajudicialmente, por terceros ajenos a estos asentamientos humanos.','77','Ley de Propiedad de Honduras (Decreto No. 82-2004)','{"norm_id":"HN:LEY_PROPIEDAD","instrumento_id":"LEY_PROPIEDAD","ingest_batch":"OLA12_LP_2007_01","ola":"OLA12","ordinal":77,"decreto":"82-2004","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición de la Corte Suprema de Justicia «Ley_de_la_Propiedad.pdf» (GNU Ghostscript, 12-abr-2007), sin notas al pie.","pdf_sha256":"ecdb725f72985a489643669300edee0f702a610bbb9c454f71daa84a6ce31785","article_sha256":"8cdc6d5896d74dd6ab598babe8bb59c353430b1c4323daf509b00c696d9a3832","ubicacion":["SECCION TERCERA","PROCESO DE REGULARIZACIÓN DE INMUEBLES POR","NECESIDAD PÚBLICA."],"constancias":[{"nota":null,"tipo":"REFORMA_TACITA","decretos":["109-2009","205-2012"],"texto":"Reformado por el Decreto No. 109-2009 y el Decreto No. 205-2012, posterior a la edición de 2007 que se usa como fuente. Las copias locales del decreto son escaneos sin capa de texto, por lo que la reforma no está integrada: el texto que se muestra es el anterior. CONTEXT vigente hasta integrar el texto de La Gaceta."}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":"CONTEXT","motivo":"CONTEXT vigente: reformado por D.109-2009 y D.205-2012 después de la edición de 2007; el texto de la reforma no está integrado (D5)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_PROPIEDAD','77','8cdc6d5896d74dd6ab598babe8bb59c353430b1c4323daf509b00c696d9a3832','OLA12_LP_2007_01',now()),
('OLA12_LP_2007_01:LEY_PROPIEDAD:78','mayalex_normativos','02_CIVIL','Asimismo, también podrá declararse de necesidad pública la regularización de la propiedad en inmuebles en las que se den conjuntamente las circunstancias siguientes:

1 Certeza mediante documento indubitado, sobre la propiedad de un inmueble en el que se encuentren asentamientos humanos contra la voluntad de su propietario desde antes del 1 de junio de 1999;

2 Sentencia firme como resultado de una acción reinvidicatoria condene al poseedor a restituirla y;

3 Que transcurridos dos (2) años de haber sido dictada la sentencia firme no haya sido ejecutada.','78','Ley de Propiedad de Honduras (Decreto No. 82-2004)','{"norm_id":"HN:LEY_PROPIEDAD","instrumento_id":"LEY_PROPIEDAD","ingest_batch":"OLA12_LP_2007_01","ola":"OLA12","ordinal":78,"decreto":"82-2004","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición de la Corte Suprema de Justicia «Ley_de_la_Propiedad.pdf» (GNU Ghostscript, 12-abr-2007), sin notas al pie.","pdf_sha256":"ecdb725f72985a489643669300edee0f702a610bbb9c454f71daa84a6ce31785","article_sha256":"06a602604fcb4b8e2da01525c786f8556651d15d23731d292e072f6a8f48b189","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_PROPIEDAD','78','06a602604fcb4b8e2da01525c786f8556651d15d23731d292e072f6a8f48b189','OLA12_LP_2007_01',now()),
('OLA12_LP_2007_01:LEY_PROPIEDAD:79','mayalex_normativos','02_CIVIL','En los casos en los dos (2) artículos precedentes, el Instituto de la Propiedad (IP) citará a las partes a una audiencia a efecto de que expongan lo que estimen convenientes en defensa de sus derechos y concilien las diferencias entre sí y con los tenedores o poseedores del inmueble. De lo ocurrido en la audiencia se levantará acta.

El acta se considerará documento indubitado y se inscribirá en el libro registro especial que se lleve en el Instituto de la Propiedad (IP) para estos propósitos.

En el caso de que no haya acuerdo a solicitud del Instituto de la Propiedad (IP); el Poder Ejecutivo en Consejo de Ministro declarará la expropiación del inmueble.','79','Ley de Propiedad de Honduras (Decreto No. 82-2004)','{"norm_id":"HN:LEY_PROPIEDAD","instrumento_id":"LEY_PROPIEDAD","ingest_batch":"OLA12_LP_2007_01","ola":"OLA12","ordinal":79,"decreto":"82-2004","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición de la Corte Suprema de Justicia «Ley_de_la_Propiedad.pdf» (GNU Ghostscript, 12-abr-2007), sin notas al pie.","pdf_sha256":"ecdb725f72985a489643669300edee0f702a610bbb9c454f71daa84a6ce31785","article_sha256":"5c86fdd51a0bac5728c773377b010e11536198ac3d1ded34c6769e6c4104c6b9","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_PROPIEDAD','79','5c86fdd51a0bac5728c773377b010e11536198ac3d1ded34c6769e6c4104c6b9','OLA12_LP_2007_01',now()),
('OLA12_LP_2007_01:LEY_PROPIEDAD:80','mayalex_normativos','02_CIVIL','La notificación de la declaratoria de expropiación del inmueble podrá hacerse personalmente o mediante el empleo de medios de comunicación masiva con presencia a nivel nacional.','80','Ley de Propiedad de Honduras (Decreto No. 82-2004)','{"norm_id":"HN:LEY_PROPIEDAD","instrumento_id":"LEY_PROPIEDAD","ingest_batch":"OLA12_LP_2007_01","ola":"OLA12","ordinal":80,"decreto":"82-2004","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición de la Corte Suprema de Justicia «Ley_de_la_Propiedad.pdf» (GNU Ghostscript, 12-abr-2007), sin notas al pie.","pdf_sha256":"ecdb725f72985a489643669300edee0f702a610bbb9c454f71daa84a6ce31785","article_sha256":"12141e9606a500d43fd95bceb03435db1c4a93b2f7e2c266714ed2027b81160b","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_PROPIEDAD','80','12141e9606a500d43fd95bceb03435db1c4a93b2f7e2c266714ed2027b81160b','OLA12_LP_2007_01',now()),
('OLA12_LP_2007_01:LEY_PROPIEDAD:81','mayalex_normativos','02_CIVIL','El propietario del inmueble expropiado no podrá ser privado del mismo sin que previamente se haya efectuado la indemnización justipreciada correspondiente.','81','Ley de Propiedad de Honduras (Decreto No. 82-2004)','{"norm_id":"HN:LEY_PROPIEDAD","instrumento_id":"LEY_PROPIEDAD","ingest_batch":"OLA12_LP_2007_01","ola":"OLA12","ordinal":81,"decreto":"82-2004","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición de la Corte Suprema de Justicia «Ley_de_la_Propiedad.pdf» (GNU Ghostscript, 12-abr-2007), sin notas al pie.","pdf_sha256":"ecdb725f72985a489643669300edee0f702a610bbb9c454f71daa84a6ce31785","article_sha256":"618cfff51e5ea418bb9d22ca5031185147a5ebd5d869f46f638ee2546f6a349b","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_PROPIEDAD','81','618cfff51e5ea418bb9d22ca5031185147a5ebd5d869f46f638ee2546f6a349b','OLA12_LP_2007_01',now()),
('OLA12_LP_2007_01:LEY_PROPIEDAD:82','mayalex_normativos','02_CIVIL','Para los efectos de la determinación del pago de la indemnización justipreciada que corresponde a quien resulte afectado por la aplicación de la presente Ley, se aplicará el procedimiento siguiente.

1 Una vez realizada la declaratoria de expropiación, el Tribunal Superior de

Cuentas (TSC) procederá a integrar una comisión evaluadora compuesta por tres (3) peritos, los cuales serán nombrados: uno por el Tribunal

Superior de Cuentas (TSC), uno por los pobladores de los asentamientos humanos beneficiados, uno por el o los propietarios del bien expropiado, cuando este definido quien es, y cuando no este definido quien es el propietario por estar en disputa la propiedad de inmueble las partes nombrarán en conjunto un representante. Si no se acreditare el nombramiento de perito por alguna de las partes dentro de los diez (10) días siguientes a la notificación el mismo será nombrado por el Tribunal

Superior de Cuentas (TSC).

2 Reunidos los peritos en el día y hora que señale el Tribunal Superior de

Cuentas (TSC), harán un avalúo los peritos tomarán por base criterios de valoración catastral, financiera, técnica y de mercado. Si la estimación de dos (2) de los peritos fuere idéntica, si la fuera una de los peritos y del nombrado por el Tribunal Superior de Cuentas (TSC) se aceptará como valor de los bienes el que establecieren las dos (2) evaluaciones conformes. No existiendo esta conformidad, se tendrá como valor de los bienes el tercio de la suma de las tres (3) operaciones; pero si entre ellas hubiere una diferencia superior al veinte (20%) respecto a la del menor valor, el Tribunal Superior de Cuentas (TSC) determinará el valor del justiprecio. Los resultados del avaluó se hará constar en acta que firmarán los miembros de la comisión evaluadora;

3 Dentro de los tres (3) días siguientes a la emisión del dictamen por parte de la comisión evaluadora, el Instituto de la Propiedad (IP) emitirá la resolución correspondiente, misma que deberá publicarse dentro de los tres (3) días de dictada; y,

4 Si el propietario o las personas que disputen el dominio del inmueble a expropiar no estuvieren de acuerdo con el justiprecio establecido en la resolución del Instituto de la Propiedad (IP), podrán recurrir por la vía judicial sujetándole al procedimiento que en materia tributaria o impositiva señala la Ley de la jurisdicción de lo Contencioso -Administrativo.','82','Ley de Propiedad de Honduras (Decreto No. 82-2004)','{"norm_id":"HN:LEY_PROPIEDAD","instrumento_id":"LEY_PROPIEDAD","ingest_batch":"OLA12_LP_2007_01","ola":"OLA12","ordinal":82,"decreto":"82-2004","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición de la Corte Suprema de Justicia «Ley_de_la_Propiedad.pdf» (GNU Ghostscript, 12-abr-2007), sin notas al pie.","pdf_sha256":"ecdb725f72985a489643669300edee0f702a610bbb9c454f71daa84a6ce31785","article_sha256":"be59edd22ffc4871e5cfbc4395acfe3ac314891c966d641646526c13f48f65e8","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_PROPIEDAD','82','be59edd22ffc4871e5cfbc4395acfe3ac314891c966d641646526c13f48f65e8','OLA12_LP_2007_01',now()),
('OLA12_LP_2007_01:LEY_PROPIEDAD:83','mayalex_normativos','02_CIVIL','Firme la resolución del Instituto de la Propiedad (IP) al pago de la indemnización correspondiente. La aceptación autoriza al Instituto de la Propiedad (IP) a inscribir el bien a favor de Honduras por su conducto.

Cuando no se pudiere hacer el pago por que el propietario se negare el mismo o no se supiere a quien hacerlo por estar en disputa la propiedad del inmueble, la indemnización se consignará en el juzgado de letras de lo Civil del lugar en que se encuentre la propiedad sin que se ofrecimiento de pago y el anuncio de la consignación. La consignación podrá ser impugnada siguiendo el procedimiento lo en el Titulo VI de la presente Ley.

Firme la Consignación, el Juez procederá a realizar la tradición de dominio a favor del Estado de Honduras por conducto del Instituto de la Propiedad (IP).','83','Ley de Propiedad de Honduras (Decreto No. 82-2004)','{"norm_id":"HN:LEY_PROPIEDAD","instrumento_id":"LEY_PROPIEDAD","ingest_batch":"OLA12_LP_2007_01","ola":"OLA12","ordinal":83,"decreto":"82-2004","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición de la Corte Suprema de Justicia «Ley_de_la_Propiedad.pdf» (GNU Ghostscript, 12-abr-2007), sin notas al pie.","pdf_sha256":"ecdb725f72985a489643669300edee0f702a610bbb9c454f71daa84a6ce31785","article_sha256":"f99878fa0cdfc7a61e3c46fcc1913f721ca2f5085b7c44beb0d1038cb1c569f7","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_PROPIEDAD','83','f99878fa0cdfc7a61e3c46fcc1913f721ca2f5085b7c44beb0d1038cb1c569f7','OLA12_LP_2007_01',now()),
('OLA12_LP_2007_01:LEY_PROPIEDAD:84','mayalex_normativos','02_CIVIL','Cuando exista controversia sobre la propiedad del inmueble los que disputen la titularidad del mismo deberán de determinar extrajudicialmente quien en ellos tiene derecho a percibir la extracción o la indemnización consignación realizada.

Cuando existan juicios pendientes sobre el inmueble expropiado los impedirán la ejecución del procedimiento establecido en este capitulo.','84','Ley de Propiedad de Honduras (Decreto No. 82-2004)','{"norm_id":"HN:LEY_PROPIEDAD","instrumento_id":"LEY_PROPIEDAD","ingest_batch":"OLA12_LP_2007_01","ola":"OLA12","ordinal":84,"decreto":"82-2004","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición de la Corte Suprema de Justicia «Ley_de_la_Propiedad.pdf» (GNU Ghostscript, 12-abr-2007), sin notas al pie.","pdf_sha256":"ecdb725f72985a489643669300edee0f702a610bbb9c454f71daa84a6ce31785","article_sha256":"444f76df583ae69d82422945e9e6d42ca45299aba5bd15d5ddc1845f8732c649","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_PROPIEDAD','84','444f76df583ae69d82422945e9e6d42ca45299aba5bd15d5ddc1845f8732c649','OLA12_LP_2007_01',now()),
('OLA12_LP_2007_01:LEY_PROPIEDAD:85','mayalex_normativos','02_CIVIL','En el decreto en que se declare la expropiación deberán de consignarse los gravámenes hipotecarios inscritos, las inscripciones y anotaciones preventivas que existan sobre el inmueble expropiado.

Los Gravámenes constituidos que pesen sobre el inmueble el inmueble quedarán garantizados por la indemnización, sin perjuicio del derecho de terceros.','85','Ley de Propiedad de Honduras (Decreto No. 82-2004)','{"norm_id":"HN:LEY_PROPIEDAD","instrumento_id":"LEY_PROPIEDAD","ingest_batch":"OLA12_LP_2007_01","ola":"OLA12","ordinal":85,"decreto":"82-2004","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición de la Corte Suprema de Justicia «Ley_de_la_Propiedad.pdf» (GNU Ghostscript, 12-abr-2007), sin notas al pie.","pdf_sha256":"ecdb725f72985a489643669300edee0f702a610bbb9c454f71daa84a6ce31785","article_sha256":"8a35fb7e51981515b0874cdc2948c9561ef8971f389f157cbf548a8117bb26e0","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_PROPIEDAD','85','8a35fb7e51981515b0874cdc2948c9561ef8971f389f157cbf548a8117bb26e0','OLA12_LP_2007_01',now()),
('OLA12_LP_2007_01:LEY_PROPIEDAD:86','mayalex_normativos','02_CIVIL','La declaración de expropiación forzosa indicada anteriormente no presumirá derecho, beneficio o perjuicio para ninguna es que se encuentren en disputa con relación a la titularidad del derecho de Propiedad inmueble.

En los casos en donde existan juicios pendientes el Instituto de la Propiedad (IP) librará comunicación al tribunal que conoce de la causa informándole sobre la declaratoria de expropiación del inmueble en litigio.','86','Ley de Propiedad de Honduras (Decreto No. 82-2004)','{"norm_id":"HN:LEY_PROPIEDAD","instrumento_id":"LEY_PROPIEDAD","ingest_batch":"OLA12_LP_2007_01","ola":"OLA12","ordinal":86,"decreto":"82-2004","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición de la Corte Suprema de Justicia «Ley_de_la_Propiedad.pdf» (GNU Ghostscript, 12-abr-2007), sin notas al pie.","pdf_sha256":"ecdb725f72985a489643669300edee0f702a610bbb9c454f71daa84a6ce31785","article_sha256":"58887d357939c3e7fd3e1d7abe2780d76bdceec996fb39156e891712f9f4f1e3","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_PROPIEDAD','86','58887d357939c3e7fd3e1d7abe2780d76bdceec996fb39156e891712f9f4f1e3','OLA12_LP_2007_01',now()),
('OLA12_LP_2007_01:LEY_PROPIEDAD:87','mayalex_normativos','02_CIVIL','una vez inscrito el inmueble a favor del Estado de Honduras a través del Instituto de la Propiedad (IP) deberá de individualizar el titular y registrar la misma a favor de los poseedores o tenedores.

La tradición del inmueble a favor de los tenedores o poseedores se hará por un precio que no podrá ser inferior al valor indemnizado.','87','Ley de Propiedad de Honduras (Decreto No. 82-2004)','{"norm_id":"HN:LEY_PROPIEDAD","instrumento_id":"LEY_PROPIEDAD","ingest_batch":"OLA12_LP_2007_01","ola":"OLA12","ordinal":87,"decreto":"82-2004","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición de la Corte Suprema de Justicia «Ley_de_la_Propiedad.pdf» (GNU Ghostscript, 12-abr-2007), sin notas al pie.","pdf_sha256":"ecdb725f72985a489643669300edee0f702a610bbb9c454f71daa84a6ce31785","article_sha256":"b65d373367e8166a2a5aaa1b8d484caa2aca62a2a8d93d404539bbffed820d48","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_PROPIEDAD','87','b65d373367e8166a2a5aaa1b8d484caa2aca62a2a8d93d404539bbffed820d48','OLA12_LP_2007_01',now()),
('OLA12_LP_2007_01:LEY_PROPIEDAD:88','mayalex_normativos','02_CIVIL','En los inmuebles donde se hayan realizado ventas inscritas en los registros de la propiedad antes de la vigencia de la presente Ley por alguno de los que se reputen dueños, se aplicará lo pagado al precio individual de venta y se deducirá del valor indemnizatorio.

Si la parte que resulte ganadora de la disputa fuere diferente aquella que realizo dichos cobros adquirirá un derecho de crédito contra aquel que lo hizo.','88','Ley de Propiedad de Honduras (Decreto No. 82-2004)','{"norm_id":"HN:LEY_PROPIEDAD","instrumento_id":"LEY_PROPIEDAD","ingest_batch":"OLA12_LP_2007_01","ola":"OLA12","ordinal":88,"decreto":"82-2004","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición de la Corte Suprema de Justicia «Ley_de_la_Propiedad.pdf» (GNU Ghostscript, 12-abr-2007), sin notas al pie.","pdf_sha256":"ecdb725f72985a489643669300edee0f702a610bbb9c454f71daa84a6ce31785","article_sha256":"0a169c3fc019371c59868f738a51a34e8dedb9f1be08bc34b0d3cff649c6690e","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_PROPIEDAD','88','0a169c3fc019371c59868f738a51a34e8dedb9f1be08bc34b0d3cff649c6690e','OLA12_LP_2007_01',now()),
('OLA12_LP_2007_01:LEY_PROPIEDAD:89','mayalex_normativos','02_CIVIL','Los bienes inmuebles poseídos en comunidad de bienes o proindivisos en los que existan cesiones de derechos inscritos en registros públicos y que en la realidad física se encuentren acotados delimitados en forma tal que permitan identificar la individualidad física de cada uno de esos derechos o cuotas de los coasignatarios, el Instituto de la Propiedad (IP) procederá a la individualización.','89','Ley de Propiedad de Honduras (Decreto No. 82-2004)','{"norm_id":"HN:LEY_PROPIEDAD","instrumento_id":"LEY_PROPIEDAD","ingest_batch":"OLA12_LP_2007_01","ola":"OLA12","ordinal":89,"decreto":"82-2004","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición de la Corte Suprema de Justicia «Ley_de_la_Propiedad.pdf» (GNU Ghostscript, 12-abr-2007), sin notas al pie.","pdf_sha256":"ecdb725f72985a489643669300edee0f702a610bbb9c454f71daa84a6ce31785","article_sha256":"d0b39a176aae7f4135a09c9fee1a6e3c1e3de34b8793adb8000068c3b13628c6","ubicacion":["SECCION CUARTA","INMUEBLES EN COMUNIDAD DE BIENES."],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_PROPIEDAD','89','d0b39a176aae7f4135a09c9fee1a6e3c1e3de34b8793adb8000068c3b13628c6','OLA12_LP_2007_01',now()),
('OLA12_LP_2007_01:LEY_PROPIEDAD:90','mayalex_normativos','02_CIVIL','Antes de proceder a la partición, los órganos jurisdiccionales competentes decidirán toda disputa sobre los derechos sujetos a partición siguiendo el procedimiento ordenado de esta Ley.

No obstante estas disputas también podrán decidirse mediante procesos de mediación, conciliación y arbitraje.','90','Ley de Propiedad de Honduras (Decreto No. 82-2004)','{"norm_id":"HN:LEY_PROPIEDAD","instrumento_id":"LEY_PROPIEDAD","ingest_batch":"OLA12_LP_2007_01","ola":"OLA12","ordinal":90,"decreto":"82-2004","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición de la Corte Suprema de Justicia «Ley_de_la_Propiedad.pdf» (GNU Ghostscript, 12-abr-2007), sin notas al pie.","pdf_sha256":"ecdb725f72985a489643669300edee0f702a610bbb9c454f71daa84a6ce31785","article_sha256":"7838eddf04dca64b2aadce1ced8c196b794c43b7f884dd6b20ecae0e60ddcd9b","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_PROPIEDAD','90','7838eddf04dca64b2aadce1ced8c196b794c43b7f884dd6b20ecae0e60ddcd9b','OLA12_LP_2007_01',now()),
('OLA12_LP_2007_01:LEY_PROPIEDAD:91','mayalex_normativos','02_CIVIL','La prescripción adquisitiva y extintiva de derecho reales sobre bienes inmuebles privada podrá ser declarada por el Instituto de la Propiedad (IP) a petición de acuerdo cuando se acrediten los extremos establecidos en el Código Civil. La posesión comenzará a contarse desde el momento en que se produjo la aprehensión material del inmueble con ánimo de dueño.

El peticionario deberá acreditar los extremos de la solicitud por cualquier medio de prueba reconocido por la legislación hondureña sin perjuicio de que el Instituto practique las investigaciones que estén pertinentes hasta emitir la resolución correspondiente.

La solicitud de declaratoria será notificada al afectado publicándolo en un diario de circulación nacional y medios radiales locales por dos (2) veces con intervalo de quince (15) días y avisos de que se expondrán en los parajes más concurridos del lugar donde está ubicado el inmuebles al costo del solicitante a efecto de cualquier interesado formule oposición dentro del termino de quince días (15) días contados a partir de la ultima publicación.

Hecha la publicación el Instituto de la Propiedad (IP) dará traslado al Juez de Letras de lo Civil del lugar donde se encuentre el inmueble para que declare la prescripción adquisitiva. Dicha sentencia servirá de titulo para su inscripción en el registro correspondiente.','91','Ley de Propiedad de Honduras (Decreto No. 82-2004)','{"norm_id":"HN:LEY_PROPIEDAD","instrumento_id":"LEY_PROPIEDAD","ingest_batch":"OLA12_LP_2007_01","ola":"OLA12","ordinal":91,"decreto":"82-2004","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición de la Corte Suprema de Justicia «Ley_de_la_Propiedad.pdf» (GNU Ghostscript, 12-abr-2007), sin notas al pie.","pdf_sha256":"ecdb725f72985a489643669300edee0f702a610bbb9c454f71daa84a6ce31785","article_sha256":"60c7a75abe695be27004338c076d4eccf991640e08705cee516049cd5bd63027","ubicacion":["SECCION QUINTA","PRESCRPCIÓN"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_PROPIEDAD','91','60c7a75abe695be27004338c076d4eccf991640e08705cee516049cd5bd63027','OLA12_LP_2007_01',now()),
('OLA12_LP_2007_01:LEY_PROPIEDAD:92','mayalex_normativos','02_CIVIL','Si el término referido se formulare oposición el Instituto remitiera los autos al Juzgado de Letras competentes para que las partes diriman su controversia conforme al procedimiento especial establecido en la presente Ley.','92','Ley de Propiedad de Honduras (Decreto No. 82-2004)','{"norm_id":"HN:LEY_PROPIEDAD","instrumento_id":"LEY_PROPIEDAD","ingest_batch":"OLA12_LP_2007_01","ola":"OLA12","ordinal":92,"decreto":"82-2004","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición de la Corte Suprema de Justicia «Ley_de_la_Propiedad.pdf» (GNU Ghostscript, 12-abr-2007), sin notas al pie.","pdf_sha256":"ecdb725f72985a489643669300edee0f702a610bbb9c454f71daa84a6ce31785","article_sha256":"b329e5c9db293de6217799d37c186f6c60e76489ee147d7663d76fdeb98517bd","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_PROPIEDAD','92','b329e5c9db293de6217799d37c186f6c60e76489ee147d7663d76fdeb98517bd','OLA12_LP_2007_01',now()),
('OLA12_LP_2007_01:LEY_PROPIEDAD:93','mayalex_normativos','02_CIVIL','El Estado, por la importancia especial que para las culturas y valores espirituales reviste su relación con las tierras, reconoce el derecho que los pueblos indígenas y afrohondureños tienen sobre las tierras que tradicionalmente poseen y que la ley no prohíbe.

El proceso establecido en el presente Capítulo será aplicado por el instituto de la Propiedad (IP) para garantizar a estos pueblos el pleno reconocimiento de los derechos de propiedad comunal, uso administración, manejo de las tierras y aprovechamiento sostenible de los recursos naturales, mediante la demarcación y titulación en dominio pleno de las mismas.','93','Ley de Propiedad de Honduras (Decreto No. 82-2004)','{"norm_id":"HN:LEY_PROPIEDAD","instrumento_id":"LEY_PROPIEDAD","ingest_batch":"OLA12_LP_2007_01","ola":"OLA12","ordinal":93,"decreto":"82-2004","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición de la Corte Suprema de Justicia «Ley_de_la_Propiedad.pdf» (GNU Ghostscript, 12-abr-2007), sin notas al pie.","pdf_sha256":"ecdb725f72985a489643669300edee0f702a610bbb9c454f71daa84a6ce31785","article_sha256":"ad8948d1550a368a4c0292aa4337aa3dd004f4e7746f992ce46eab52d7d4c507","ubicacion":["CAPITULO III","DEL PROCESO DE REGULARIZACIÓN DE LA PROPIEDAD","INMUEBLE PARA PUEBLOS INDIGENAS Y AFROHONDUREÑOS."],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_PROPIEDAD','93','ad8948d1550a368a4c0292aa4337aa3dd004f4e7746f992ce46eab52d7d4c507','OLA12_LP_2007_01',now()),
('OLA12_LP_2007_01:LEY_PROPIEDAD:94','mayalex_normativos','02_CIVIL','Los derechos de propiedad sobre las tierras de estos pueblos se titularán a su favor en forma colectiva. Los miembros de las comunidades tienen derecho de tenencia usufructo de acuerdo a las formas tradicionales de tenencia de la propiedad comunal.','94','Ley de Propiedad de Honduras (Decreto No. 82-2004)','{"norm_id":"HN:LEY_PROPIEDAD","instrumento_id":"LEY_PROPIEDAD","ingest_batch":"OLA12_LP_2007_01","ola":"OLA12","ordinal":94,"decreto":"82-2004","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición de la Corte Suprema de Justicia «Ley_de_la_Propiedad.pdf» (GNU Ghostscript, 12-abr-2007), sin notas al pie.","pdf_sha256":"ecdb725f72985a489643669300edee0f702a610bbb9c454f71daa84a6ce31785","article_sha256":"220703b8b0aaccc909a5c9e15eb1033c2e1ceb8d6d7215bbfffe4744e7184a4a","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_PROPIEDAD','94','220703b8b0aaccc909a5c9e15eb1033c2e1ceb8d6d7215bbfffe4744e7184a4a','OLA12_LP_2007_01',now()),
('OLA12_LP_2007_01:LEY_PROPIEDAD:95','mayalex_normativos','02_CIVIL','En caso de que el Estado pretenda la explotación de recursos naturales en los territorios de estos pueblos deberá de informarles consultarles sobre los beneficios y perjuicios que puedan sobrevivir previo a autorizar cualquier inspección, o explotación.

En caso de que autorice cualquier tipo de explotación, los pueblos deben de percibir una indemnización equitativa por cualquier daño que tuvieran como resultados de esas actividades.','95','Ley de Propiedad de Honduras (Decreto No. 82-2004)','{"norm_id":"HN:LEY_PROPIEDAD","instrumento_id":"LEY_PROPIEDAD","ingest_batch":"OLA12_LP_2007_01","ola":"OLA12","ordinal":95,"decreto":"82-2004","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición de la Corte Suprema de Justicia «Ley_de_la_Propiedad.pdf» (GNU Ghostscript, 12-abr-2007), sin notas al pie.","pdf_sha256":"ecdb725f72985a489643669300edee0f702a610bbb9c454f71daa84a6ce31785","article_sha256":"4bfcf18024c257d905558eae0401048685e7d8118867b9df6d0d3e7938650287","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_PROPIEDAD','95','4bfcf18024c257d905558eae0401048685e7d8118867b9df6d0d3e7938650287','OLA12_LP_2007_01',now()),
('OLA12_LP_2007_01:LEY_PROPIEDAD:96','mayalex_normativos','02_CIVIL','Los derechos de propiedad y tenencia de estos pueblos prevalecerán sobre estos títulos emitidos a favor de terceros que nunca las han poseído.','96','Ley de Propiedad de Honduras (Decreto No. 82-2004)','{"norm_id":"HN:LEY_PROPIEDAD","instrumento_id":"LEY_PROPIEDAD","ingest_batch":"OLA12_LP_2007_01","ola":"OLA12","ordinal":96,"decreto":"82-2004","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición de la Corte Suprema de Justicia «Ley_de_la_Propiedad.pdf» (GNU Ghostscript, 12-abr-2007), sin notas al pie.","pdf_sha256":"ecdb725f72985a489643669300edee0f702a610bbb9c454f71daa84a6ce31785","article_sha256":"b8be88799b87136c8e3ed18043b5386775cdc89035806fb7259d8a6de3abd6ed","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_PROPIEDAD','96','b8be88799b87136c8e3ed18043b5386775cdc89035806fb7259d8a6de3abd6ed','OLA12_LP_2007_01',now()),
('OLA12_LP_2007_01:LEY_PROPIEDAD:97','mayalex_normativos','02_CIVIL','El tercero que tengan título de propiedad en tierras estos pueblos y que han tenido y poseído la tierra amparada por ese lo tiene, derecho de continuar poseyéndola y explotándola.','97','Ley de Propiedad de Honduras (Decreto No. 82-2004)','{"norm_id":"HN:LEY_PROPIEDAD","instrumento_id":"LEY_PROPIEDAD","ingest_batch":"OLA12_LP_2007_01","ola":"OLA12","ordinal":97,"decreto":"82-2004","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición de la Corte Suprema de Justicia «Ley_de_la_Propiedad.pdf» (GNU Ghostscript, 12-abr-2007), sin notas al pie.","pdf_sha256":"ecdb725f72985a489643669300edee0f702a610bbb9c454f71daa84a6ce31785","article_sha256":"e000e7a8fd516ba683f48170320d324b5a4a83ade0dee5e9b9721b9bd242b47f","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_PROPIEDAD','97','e000e7a8fd516ba683f48170320d324b5a4a83ade0dee5e9b9721b9bd242b47f','OLA12_LP_2007_01',now()),
('OLA12_LP_2007_01:LEY_PROPIEDAD:98','mayalex_normativos','02_CIVIL','El tercero que ha recibido título de propiedad en tierras comunales de estos pueblos, que por sus características pudiera anulable, previo a la devolución de las tierras a las comunidades afectadas será indemnizado en sus mejoras.','98','Ley de Propiedad de Honduras (Decreto No. 82-2004)','{"norm_id":"HN:LEY_PROPIEDAD","instrumento_id":"LEY_PROPIEDAD","ingest_batch":"OLA12_LP_2007_01","ola":"OLA12","ordinal":98,"decreto":"82-2004","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición de la Corte Suprema de Justicia «Ley_de_la_Propiedad.pdf» (GNU Ghostscript, 12-abr-2007), sin notas al pie.","pdf_sha256":"ecdb725f72985a489643669300edee0f702a610bbb9c454f71daa84a6ce31785","article_sha256":"0a20eedcf5b2560592cd80037bc75f87c5d87ec82b73382c559cb07fd4816c49","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_PROPIEDAD','98','0a20eedcf5b2560592cd80037bc75f87c5d87ec82b73382c559cb07fd4816c49','OLA12_LP_2007_01',now()),
('OLA12_LP_2007_01:LEY_PROPIEDAD:99','mayalex_normativos','02_CIVIL','Los terceros en tierras de estos pueblos sin título alguna no podrán negociar su permanencia con la comunidad pagando el de arrendamiento que acuerden.','99','Ley de Propiedad de Honduras (Decreto No. 82-2004)','{"norm_id":"HN:LEY_PROPIEDAD","instrumento_id":"LEY_PROPIEDAD","ingest_batch":"OLA12_LP_2007_01","ola":"OLA12","ordinal":99,"decreto":"82-2004","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición de la Corte Suprema de Justicia «Ley_de_la_Propiedad.pdf» (GNU Ghostscript, 12-abr-2007), sin notas al pie.","pdf_sha256":"ecdb725f72985a489643669300edee0f702a610bbb9c454f71daa84a6ce31785","article_sha256":"dfbb7f52535854106ed50f069a42b988ad7d4e8c1b35dabc32e3f88a53d218e2","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_PROPIEDAD','99','dfbb7f52535854106ed50f069a42b988ad7d4e8c1b35dabc32e3f88a53d218e2','OLA12_LP_2007_01',now()),
('OLA12_LP_2007_01:LEY_PROPIEDAD:100','mayalex_normativos','02_CIVIL','Se declara y reconoce que el régimen comunal de las tierras que tradicionalmente poseen estos pueblos conlleva la inalienabilidad, inembargabilidad e imprescriptibilidad de la misma.

No obstante, las mismas comunidades podrán poner fin a este régimen comunal, autorizar arrendamientos a favor de terceros o autorizar contratos de otra naturaleza que permitan la participación de la comunidad en inversiones que contribuyan a su desarrollo.','100','Ley de Propiedad de Honduras (Decreto No. 82-2004)','{"norm_id":"HN:LEY_PROPIEDAD","instrumento_id":"LEY_PROPIEDAD","ingest_batch":"OLA12_LP_2007_01","ola":"OLA12","ordinal":100,"decreto":"82-2004","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición de la Corte Suprema de Justicia «Ley_de_la_Propiedad.pdf» (GNU Ghostscript, 12-abr-2007), sin notas al pie.","pdf_sha256":"ecdb725f72985a489643669300edee0f702a610bbb9c454f71daa84a6ce31785","article_sha256":"e77f2d0bf0f715fadf13291f78b1ac338a19dc9769f102d9e472b804ac345bdb","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_PROPIEDAD','100','e77f2d0bf0f715fadf13291f78b1ac338a19dc9769f102d9e472b804ac345bdb','OLA12_LP_2007_01',now())
